import type { QDef, TestDef } from '../types';
import data from './mocks.json';

/**
 * Real past-paper questions (reported by candidates from earlier MIFOTRA written exams), each answer checked against the law
 * as it stands today and generated by the past-paper build. `overrides` replaces a mock's whole question list (same sections,
 * same number of questions); `extras` are further mocks built from the questions that did not fit in the original five.
 */
interface PastPaperData {
  overrides: Record<string, QDef[]>;
  extras: TestDef[];
}

const PAST = data as unknown as PastPaperData;

export function applyPastPapers(tests: TestDef[]): TestDef[] {
  const out = tests.map((t) => {
    const questions = PAST.overrides[t.slug];
    return questions ? { ...t, questions } : t;
  });
  return [...out, ...PAST.extras];
}
